const { execSync } = require('child_process');
const fs = require('fs');
const url = $input.item.json.body.url;

if (!url) throw new Error('URL não informada no body');

const out = 'C:\\Users\\Admin\\.n8n-files\\podcast.mp3';
const tmp = 'C:\\Users\\Admin\\.n8n-files\\podcast_tmp.mp3';

// Download
execSync(`yt-dlp -x --audio-format mp3 --audio-quality 0 -o "${out}" "${url}"`, { stdio: 'inherit' });

// Groq limit = 25 MB. Re-encode to lower bitrate if needed.
const sizeMB = fs.statSync(out).size / (1024 * 1024);
if (sizeMB > 24) {
  const bitrate = sizeMB > 50 ? '16k' : '32k';
  execSync(`ffmpeg -y -i "${out}" -b:a ${bitrate} -ac 1 "${tmp}"`, { stdio: 'inherit' });
  fs.renameSync(tmp, out);
}

return [{ json: { status: 'downloaded', youtube_url: url } }];

const https = require('https');
const summary = $input.item.json.summary;
const youtubeUrl = $input.item.json.youtube_url;

// Extract FRASE DO EPISÓDIO - grab first content line after section header
let titulo = 'Podcast Processado';
const epIdx = summary.search(/FRASE DO EPIS/i);
if (epIdx !== -1) {
  const afterFrase = summary.substring(epIdx);
  for (const line of afterFrase.split('\n')) {
    const t = line.trim();
    if (!t || t.match(/FRASE DO EPIS/i) || t.match(/^---/)) continue;
    const clean = t.replace(/^>\s*/, '').replace(/\*/g, '')
                    .replace(/^"+/, '').replace(/"+$/, '')
                    .replace(/\s*—.*$/, '').trim();
    if (clean.length > 10) { titulo = clean; break; }
  }
}

// Extract TEMAS DISCUTIDOS bullet topics
const temas = [];
const temasMatch = summary.match(/\*\*TEMAS DISCUTIDOS[^*]*\*\*([\s\S]*?)\*\*CONCLUSÕES/);
if (temasMatch) {
  for (const m of temasMatch[1].matchAll(/- \*\*([^*:]+)/g)) {
    temas.push({ name: m[1].trim().replace(/,/g, ' e') });
  }
}

// YouTube thumbnail
const vidMatch = youtubeUrl.match(/[?&]v=([^&\s]+)/);
const videoId = vidMatch ? vidMatch[1] : '';

function parseInline(txt) {
  const parts = [];
  const re = /\*\*(.+?)\*\*|\*([^*\n]+)\*/g;
  let last = 0, m;
  while ((m = re.exec(txt)) !== null) {
    if (m.index > last) parts.push({ type: 'text', text: { content: txt.slice(last, m.index) } });
    if (m[1] !== undefined) {
      parts.push({ type: 'text', text: { content: m[1] }, annotations: { bold: true } });
    } else {
      parts.push({ type: 'text', text: { content: m[2] }, annotations: { italic: true } });
    }
    last = m.index + m[0].length;
  }
  if (last < txt.length) parts.push({ type: 'text', text: { content: txt.slice(last) } });
  return parts.length ? parts : [{ type: 'text', text: { content: txt } }];
}

function mdToBlocks(md) {
  const blocks = [];
  const lines = md.split('\n');
  let i = 0;
  while (i < lines.length) {
    const t = lines[i].trim();
    if (!t) { i++; continue; }
    if (t === '---') { blocks.push({ object: 'block', type: 'divider', divider: {} }); i++; continue; }
    if (/^\*\*[^*]+\*\*$/.test(t)) {
      const txt = t.slice(2, -2);
      const hType = txt === txt.toUpperCase() ? 'heading_2' : 'heading_3';
      blocks.push({ object: 'block', type: hType, [hType]: { rich_text: [{ type: 'text', text: { content: txt } }] } });
      i++; continue;
    }
    if (t.startsWith('- ')) { blocks.push({ object: 'block', type: 'bulleted_list_item', bulleted_list_item: { rich_text: parseInline(t.slice(2)) } }); i++; continue; }
    if (t.startsWith('> ')) {
      blocks.push({ object: 'block', type: 'quote', quote: { rich_text: parseInline(t.slice(2)) } });
      i++; continue;
    }
    const paraLines = [];
    while (i < lines.length) {
      const pt = lines[i].trim();
      if (!pt || pt === '---' || /^\*\*[^*]+\*\*$/.test(pt) || pt.startsWith('- ') || pt.startsWith('> ')) break;
      paraLines.push(pt); i++;
    }
    const paraText = paraLines.join(' ');
    for (let s = 0; s < paraText.length || s === 0; s += 1900) {
      const chunk = paraText.slice(s, s + 1900);
      if (chunk) blocks.push({ object: 'block', type: 'paragraph', paragraph: { rich_text: parseInline(chunk) } });
    }
  }
  return blocks;
}

const children = [];
if (videoId) {
  children.push({ object: 'block', type: 'image', image: { type: 'external', external: { url: `https://img.youtube.com/vi/${videoId}/0.jpg` } } });
}
children.push(...mdToBlocks(summary));

const body = {
  parent: { database_id: 'YOUR_NOTION_DATABASE_ID' },
  properties: {
    'Título': { title: [{ text: { content: titulo.substring(0, 2000) } }] },
    'URL do YouTube': { url: youtubeUrl },
    'Data de Processamento': { date: { start: new Date().toISOString().split('T')[0] } },
    'Temas Principais': { multi_select: temas.slice(0, 10) },
    'Status': { select: { name: 'Processado' } }
  },
  children: children.slice(0, 100)
};

function notionReq(method, path, reqBody) {
  return new Promise((resolve, reject) => {
    const bodyStr = JSON.stringify(reqBody);
    const opts = {
      hostname: 'api.notion.com', port: 443, path, method,
      headers: {
        'Authorization': 'Bearer YOUR_NOTION_TOKEN',
        'Content-Type': 'application/json',
        'Notion-Version': '2022-06-28',
        'Content-Length': Buffer.byteLength(bodyStr)
      }
    };
    const req = https.request(opts, (res) => {
      let raw = '';
      res.on('data', c => raw += c);
      res.on('end', () => {
        const parsed = JSON.parse(raw);
        if (res.statusCode < 200 || res.statusCode >= 300)
          reject(new Error(`Notion error ${res.statusCode}: ${JSON.stringify(parsed)}`));
        else resolve(parsed);
      });
    });
    req.on('error', reject);
    req.write(bodyStr);
    req.end();
  });
}

const page = await notionReq('POST', '/v1/pages', body);

for (let i = 100; i < children.length; i += 100) {
  await notionReq('PATCH', `/v1/blocks/${page.id}/children`, { children: children.slice(i, i + 100) });
}

return [{ json: {
  notion_page_id: page.id,
  notion_url: page.url,
  titulo,
  temas: temas.map(t => t.name),
  youtube_url: youtubeUrl,
  status: 'Processado'
} }];

const fs = require('fs');
try { fs.unlinkSync('C:\\Users\\Admin\\.n8n-files\\podcast.mp3'); } catch(e) {}
return [{ json: $input.item.json }];

